def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4

    # Fit each patterned row independently. The repeated sequence may have
    # a different period/palette in different task instances.
    for r in range(3, h):
        known = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        if not known:
            continue
        best = None
        for p in range(2, 11):
            slots = []
            score = 0
            for k in range(p):
                counts = {}
                for c, v in known:
                    if c % p == k:
                        counts[v] = counts.get(v, 0) + 1
                if counts:
                    value, n = max(counts.items(), key=lambda item: item[1])
                    slots.append(value)
                    score += n
                else:
                    slots.append(None)
            # Prefer simpler periods when fits are equally good.
            candidate = (score, -p, slots, p)
            if best is None or candidate[:2] > best[:2]:
                best = candidate
        _, _, slots, p = best
        for c in range(3, w):
            if grid[r][c] == 0:
                v = slots[c % p]
                if v is None:
                    nearest = min(
                        (abs(cc-c), grid[r][cc])
                        for cc in range(3, w) if grid[r][cc] != 0
                    )
                    v = nearest[1]
                out[r][c] = v
    return out
